window.ScripturaLexicons.BDAG_PART_0221 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-01\" data-source=\"BDAG\" data-search=\"Λουκᾶς, ᾶ, ὁ nome próprio masculino Lucas; cooperador de Paulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λουκᾶς, ᾶ, ὁ</td><td>nome próprio masculino</td><td>Lucas; cooperador de Paulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-02\" data-source=\"BDAG\" data-search=\"Λούκιος, ου, ὁ nome próprio masculino Lúcio; nome romano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λούκιος, ου, ὁ</td><td>nome próprio masculino</td><td>Lúcio; nome romano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-03\" data-source=\"BDAG\" data-search=\"λουτρόν, οῦ, τό substantivo neutro banho; lavagem batismal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λουτρόν, οῦ, τό</td><td>substantivo neutro</td><td>banho; lavagem batismal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-04\" data-source=\"BDAG\" data-search=\"λούω verbo lavar; banhar; purificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λούω</td><td>verbo</td><td>lavar; banhar; purificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-05\" data-source=\"BDAG\" data-search=\"Λύδδα topônimo Lida; cidade perto de Jope BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λύδδα</td><td>topônimo</td><td>Lida; cidade perto de Jope</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-06\" data-source=\"BDAG\" data-search=\"Λυδία, ας, ἡ nome próprio feminino Lídia; comerciante de púrpura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυδία, ας, ἡ</td><td>nome próprio feminino</td><td>Lídia; comerciante de púrpura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-07\" data-source=\"BDAG\" data-search=\"Λυκαονία, ας, ἡ topônimo feminino Licaônia; região da Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυκαονία, ας, ἡ</td><td>topônimo feminino</td><td>Licaônia; região da Ásia Menor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-08\" data-source=\"BDAG\" data-search=\"Λυκαονιστί advérbio na língua licaônica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυκαονιστί</td><td>advérbio</td><td>na língua licaônica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-09\" data-source=\"BDAG\" data-search=\"Λυκία, ας, ἡ topônimo feminino Lícia; região da Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυκία, ας, ἡ</td><td>topônimo feminino</td><td>Lícia; região da Ásia Menor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-10\" data-source=\"BDAG\" data-search=\"λύκος, ου, ὁ substantivo masculino lobo; pessoa cruel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύκος, ου, ὁ</td><td>substantivo masculino</td><td>lobo; pessoa cruel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-11\" data-source=\"BDAG\" data-search=\"λυμαίνω verbo prejudicar; arruinar; destruir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυμαίνω</td><td>verbo</td><td>prejudicar; arruinar; destruir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-12\" data-source=\"BDAG\" data-search=\"λυπέω verbo afligir; entristecer; ofender BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυπέω</td><td>verbo</td><td>afligir; entristecer; ofender</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-13\" data-source=\"BDAG\" data-search=\"λύπη, ης, ἡ substantivo feminino tristeza; dor; aflição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύπη, ης, ἡ</td><td>substantivo feminino</td><td>tristeza; dor; aflição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-14\" data-source=\"BDAG\" data-search=\"λυπηρός, ά, όν adjetivo doloroso; triste; pesaroso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυπηρός, ά, όν</td><td>adjetivo</td><td>doloroso; triste; pesaroso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-15\" data-source=\"BDAG\" data-search=\"Λυσανίας, ου, ὁ nome próprio masculino Lisânias; tetrarca de Abilene BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυσανίας, ου, ὁ</td><td>nome próprio masculino</td><td>Lisânias; tetrarca de Abilene</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-16\" data-source=\"BDAG\" data-search=\"Λυσίας, ου, ὁ nome próprio masculino Lísias; comandante romano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λυσίας, ου, ὁ</td><td>nome próprio masculino</td><td>Lísias; comandante romano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-17\" data-source=\"BDAG\" data-search=\"λύσις, εως, ἡ substantivo feminino libertação; separação; divórcio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λύσις, εως, ἡ</td><td>substantivo feminino</td><td>libertação; separação; divórcio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-18\" data-source=\"BDAG\" data-search=\"λυσιτελέω verbo ser vantajoso; ser melhor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυσιτελέω</td><td>verbo</td><td>ser vantajoso; ser melhor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-19\" data-source=\"BDAG\" data-search=\"λυσσάω verbo estar furioso; estar raivoso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λυσσάω</td><td>verbo</td><td>estar furioso; estar raivoso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0221-20\" data-source=\"BDAG\" data-search=\"Λύστρα topônimo Listra; cidade da Licaônia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λύστρα</td><td>topônimo</td><td>Listra; cidade da Licaônia</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0221-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λουκᾶς, ᾶ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λουκᾶς</span>, <span class=\"greek\">ᾶ</span>, <span class=\"greek\">ὁ</span> (como nome greco-romano CIG III, 4759; III, add. 4700k; 4790; inscrição em Antioquia da Pisídia: Ramsay, Bearing 370–84; CIL VI, 17685; Ephem. Epigr. VIII/3 no. 477; Sb 224) Lucas (forma carinhosa ou hipocorística de Lúcio [outra inscrição de Antioquia da Pisídia, estreitamente relacionada à mencionada acima—Ramsay, loc. cit.—designa como <span class=\"greek\">Λούκιος</span> o homem chamado <span class=\"greek\">Λουκᾶς</span> na primeira]: WSchulze, Graeca Latina 1901, 12; B-D-F §125, 2; Mlt-H. 88 [prefere Lucanus]; Dssm., Festgabe für AvHarnack 1921, 117–20=LO 372–77 [LAE2 435ff] com inscrições; EKlostermann, Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:1</a> [considera ainda outras possibilidades]), companheiro e cooperador de Paulo Phlm 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:11</a>; 2 Cor subscr.; cf. a reconstituição AcPl Ha 11, 16, baseada em Aa I 116, 17; 117, 5; segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:14</a>, médico (cf. Lucian, Pereg. 44 <span class=\"greek\">Ἀλέξ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἰατρός</span>), e conforme a tradição (Iren. 3, 1, 1 [Harv. II 6, 1]; Murat. Canon 2–8; 34–39) autor do terceiro Evangelho, Lk title <span class=\"greek\">κατὰ</span> <span class=\"greek\">Λουκᾶν</span>, e título de Atos, variante textual (ApcEsdr 5:22 <span class=\"greek\">Πέτρον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Παῦλον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Λουκᾶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Ματθείαν</span>). A proposição de que a linguagem desses livros demonstra que o autor era médico (so Hobart; Harnack [s. below] 122ff; Zahn, Einl.3 II 433ff e outros) é contestada por GAvdBerghvanEysinga, De geneesher L.: NThT 5, 1916, 228–50; Cadbury, Style, 39ff, JBL 45, 1926, 190–209 e outros A ideia, conhecida desde Orígenes, In Rom. Comm. 10, 39, de que Lucas deve ser identificado com o Lúcio de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:21</a> (<span class=\"greek\">Λούκιος</span> 2) foi retomada por Dssm., loc. cit. Efrém, o Sírio, identificou L. com Lúcio de Cirene (<span class=\"greek\">Λούκιος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a> (AMerk, D. neuentdeckte Komm. d. hl. E. zur AG: ZKT 48, 1924, 54).—Harnack, Lukas d. Arzt 1906; Ramsay, Luke the Physician 1908; AvanVeldhuizen, Lukas de medicijnmeester 1926; HCadbury, The Making of Luke-Acts 1927; EMeyer I 1ff; 46ff; 100ff; 304ff. WReilly, CBQ 1, ’39, 314–24.—TRE III 483–528. ABD IV 401f (bibliografia). LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λούκιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λούκιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Diod S 11, 81, 1; 12, 43, 1; 14, 38, 1; SIG 1173, 7; Sb II 258f; PFay 110, 1 [94 d.C.]; PWarr 1, 1; PVindobBosw 2, 11; Jos., Bell. 6, 188; Just., A I, 1, 1 [Vero, filho adotivo de Antônio]; A II 2, 15 <span class=\"greek\">Λούκιός</span> <span class=\"greek\">τις</span> al.; Ath. ins [Cômodo]; B-D-F §41, 1; Mlt-H. 88) Lúcio.</p><p class=\"entry-text\">① de Cirene, mestre ou profeta em Antioquia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a>.—HCadbury, Beginn. I 5, ’33, 489–95.</p><p class=\"entry-text\">② cristão desconhecido por outras fontes, que envia uma saudação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:21</a>.—Quanto a ambos, veja <span class=\"greek\">Λουκάς</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λουτρόν, οῦ, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λουτρόν</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">λούω</span>; desde Homero [<span class=\"greek\">λοετρόν</span>], com forma contraída desde Hesíodo; ins, pap; SSol 4:2; 6:6; Sir 34:25; Jos., Ant. 8, 356; Just.; Mel.) banho, lavagem batismal (quanto ao uso cerimonial, cf. Ael. Aristid. 48, 71 K.=24 p. 483 D.: <span class=\"greek\">λουτρὰ</span> <span class=\"greek\">θεῖα</span>; Arrian, Tact. 33, 4; Philostrat. Junior [século III d.C.] ao final de suas <span class=\"greek\">Εἰκόνες</span> [APF 14, ’41] ln. 77, p. 8; 19 <span class=\"greek\">λουτρὰ</span> <span class=\"greek\">σεμνά</span>; inscrição de culto mistérico proveniente de Andânia: SIG 736, 106 [92 a.C.]; Philo, Cher. 95 al.; veja também <span class=\"greek\">λούω</span> 2; Hippol., Ref. 5, 27, 2) <span class=\"greek\">τὸ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὕδατος</span> a lavagem com água <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:26</a> (Jos., C. Ap. 1, 282 <span class=\"greek\">ὑδάτων</span> <span class=\"greek\">λουτροῖς</span>; Just., A I, 61, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ὕδατι</span> … <span class=\"greek\">λουτρόν</span>). <span class=\"greek\">λ</span>. <span class=\"greek\">παλιγγενεσίας</span> o banho que produz regeneração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:5</a> (cf. Philo, Mut. Nom. 124 <span class=\"greek\">τοῖς</span> <span class=\"greek\">φρονήσεως</span> <span class=\"greek\">λουτροῖς</span> <span class=\"greek\">χρησαμένη</span> [<span class=\"greek\">ἡ</span> <span class=\"greek\">ψυχή</span>]; Just., A I, 66, 1 <span class=\"greek\">τὸ</span> … <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀναγέννησιν</span> <span class=\"greek\">λουτρόν</span>).—DELG s.v. <span class=\"greek\">λούω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λούω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λούω</span> (veja o verbete anterior; desde Homero) futuro <span class=\"greek\">λούσω</span> LXX; 1º aoristo <span class=\"greek\">ἔλουσα</span>. Voz passiva: 1º aoristo, 2ª pessoa do singular <span class=\"greek\">ἐλούσθης</span> Ezk 16:4; particípio perfeito <span class=\"greek\">λελουμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10</a> e <span class=\"greek\">λελουσμένος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a> (B-D-F §70, 3; W-S. §13, 1; Mlt-H. 248; Helbing 100f)</p><p class=\"entry-text\">① empregar água para limpar um corpo de impurezas físicas; lavar, geralmente o corpo inteiro, banhar</p><p class=\"entry-text\">ⓐ na voz ativa, com uso absoluto, quanto à lavagem de um cadáver (Homero e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:37</a>; GPt 6:24. Quanto a pessoas que foram açoitadas <span class=\"greek\">ἔλουσεν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πληγῶν</span> lavou-lhes as feridas (literalmente «pela lavagem, livrou-os dos efeitos dos golpes») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:33</a> (quanto à construção com <span class=\"greek\">ἀπό</span>, veja 3 abaixo. Também Antig. Car. 163 quanto a Europa: <span class=\"greek\">λούσασθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διὸς</span> <span class=\"greek\">μίξεως</span>=lavar os vestígios da união sexual com Zeus). Quanto à variante textual de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:5</a>, veja 3.</p><p class=\"entry-text\">ⓑ na voz média, lavo-me, banho-me (Homero e outros); literalmente, de pessoa ou animal: quanto a uma mulher <span class=\"greek\">λουομένη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ποταμόν</span> banhando-se no rio Hv 1, 1, 2 (<span class=\"greek\">λ</span>. <span class=\"greek\">εἰς</span> também Ptolem. Euerg. II [século II a.C.]: 234 Fgm. 3 Jac.; Alciphron 3, 7, 1 <span class=\"greek\">λουσάμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">βαλανεῖον</span>; Cyranides p. 57, 6; Iren. 3, 3, 4 [Harv. II 13, 11 e 12]). <span class=\"greek\">ὗς</span> <span class=\"greek\">λουσαμένη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:22</a> (veja <span class=\"greek\">βόρβορος</span> 2).</p><p class=\"entry-text\">② empregar água ritualmente para purificação; lavar-se, banhar-se, purificar-se; na voz média, quanto às abluções cultuais</p><p class=\"entry-text\">ⓐ (Soph., Ant. 1201 <span class=\"greek\">τὸν</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">λούσαντες</span> <span class=\"greek\">ἁγνὸν</span> <span class=\"greek\">λουτρόν</span>; Apollon. Rhod. 3, 1203 <span class=\"greek\">λοέσσατο</span> <span class=\"greek\">ποταμοῖο</span> … <span class=\"greek\">θείοιο</span> … antes do sacrifício, Jasão lavou-se das impurezas no rio divino; Plut., Mor. 264d <span class=\"greek\">λούσασθαι</span> <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θυσίας</span>; Ael. Aristid. 33, 32 K.=51 p. 582 D.: <span class=\"greek\">πρὸς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">λούσασθαι</span> <span class=\"greek\">κέρδος</span> <span class=\"greek\">ἐστὶ</span> <span class=\"greek\">ζῶντα</span>, <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τελευτήσαντι</span> <span class=\"greek\">μένει</span>; Dssm., NB 54 [BS 226f] cita, para esse uso, três inscrições, todas na voz média, duas combinadas com <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>; Sb 4127, 14 <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἁγίῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀθανασίας</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">λουσάμενος</span>; Ramsay, Exp. 7th ser., 8, 1909, p. 280, 1; LXX; Jos., Vi. 11 <span class=\"greek\">λ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ἁγνείαν</span>) quanto ao ato de purificação exigido antes de entrar no templo Ox 840, 14; 19; 24f (<span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">λίμνῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Δαυίδ</span>); 32 (<span class=\"greek\">ὕδασιν</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">λελουμένος</span> aquele que se banhou (em contraste com aquele cujos pés são lavados, com alusão à lavagem de todo o corpo no batismo [<span class=\"greek\">λελουμένος</span> ‘recém-banhado, depois do banho’ Hdt. 1, 126; Aristoph., Lysist. 1064; Plut., Mor. 958b <span class=\"greek\">λουσαμένοις</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">νιψαμένοις</span>; Lev 15:11 <span class=\"greek\">τ</span>. <span class=\"greek\">χεῖρας</span> <span class=\"greek\">νίπτεσθαι</span>, <span class=\"greek\">λούεσθαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span>]; de maneira diferente, HWindisch, Johannes u. d. Synoptiker 1926, 77. Sobre o lava-pés, veja também GKnight, Feetwashing: Enc. of Rel. and Ethics V 814–23; PFiebig, <span class=\"greek\">Αγγελος</span> III 1930, 121–28; BBacon, ET 43, ’32, 218–21; HvCampenhausen, ZNW 33, ’34, 259–71; FBraun, RB 44, ’35, 22–33; ELohmeyer, ZNW 38, ’39, 74–94; AFridrichsen, ibid. 94–96; Bultmann, comm. J ad loc., 355–65; JDunn, ZNW 61, ’70, 247–52) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:10</a> (<span class=\"greek\">λού</span>. ao lado de <span class=\"greek\">νίπτ</span>. no contexto de refeição em Tob 7:9 S; <span class=\"greek\">λού</span>. antes da refeição em AcThom 89=Aa p. 204 l. 7f). <span class=\"greek\">λούσασθε</span> lavai-vos 1 Cl 8:4 (Is 1:16). Sempre quanto ao batismo (Hippol., Ref. 5, 7, 19) AcPl Ha 2, 35; 3, 6; 5, 1f; 7, 20.—O significado é duvidoso em <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">μεταλάβῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λούσεται</span> se alguém recebe o corpo do Senhor (na Eucaristia) e depois enxágua a boca ou toma banho Agr 19.</p><p class=\"entry-text\">ⓑ Lavo para mim mesmo, com objeto no acusativo (desde Hesíodo) <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">ὕδατι</span> <span class=\"greek\">καθαρῷ</span> (cf. Dt 23:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:22</a> (quanto ao batismo).</p><p class=\"entry-text\">③ causar purificação, purificar; na voz ativa (figuradamente, mediante líquido diferente da água) <span class=\"greek\">τῷ</span> <span class=\"greek\">λούσαντι</span> <span class=\"greek\">ἡμᾶς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτιῶν</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:5</a> variante textual (quanto ao emprego de agente diferente da água com <span class=\"greek\">λ</span>., mas em sentido diverso, veja Simonid. 144 um arco banhado em sangue [Diehl2 II p. 113=Bergk 143]; Lucian, Dial. Meretr. 13, 3 pessoas banhadas em sangue.) Sobre essa leitura, veja PvonderOsten-Sacken, ZNW 58, ’67, 258 n. 17.—B. 579. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λύδδα</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λύδδα</span> (<span class=\"hebrew\" dir=\"rtl\">לוֹד</span>.—1 Macc 11:34; Joseph. index), genitivo <span class=\"greek\">Λύδδας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:38</a> (veja Thackeray 161), onde também se atesta <span class=\"greek\">Λύδδης</span>. O acusativo <span class=\"greek\">Λύδδα</span> (Jos., Bell. 2, 242; 515 ao lado de <span class=\"greek\">Λύδδαν</span> Ant. 20, 130) vss. 32, 35 (ambas variantes textuais em -<span class=\"greek\">αν</span>) funciona como forma indeclinável ou neutro plural (Jos., Bell. 1, 302 <span class=\"greek\">ἐν</span> <span class=\"greek\">Λύδδοις</span>; 2, 244; 4, 444; s. B-D-F §56, 2), <span class=\"greek\">ἡ</span>, Lida, cidade a cerca de 17 km a sudeste de Jope, na estrada para Jerusalém. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:32</a>, 35, 38. Schürer index, especialmente II 193, 34; BHHW II 1101; Kl. Pauly III 797.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυδία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (como nome feminino Horace, Odes 1, 8, 1; 1, 13, 1; 1, 25, 8; 3, 9, 6f; Martial, Epigr. 11, 21. Em grego, conservado na forma <span class=\"greek\">Λύδη</span>: CIG 653; 6975; CIA III, 3261f) Lídia, comerciante de Tiatira, na Lídia, que negociava tecidos de púrpura; foi convertida por Paulo em Filipos, depois de ter sido <span class=\"greek\">σεβομένη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεόν</span> (veja <span class=\"greek\">σέβω</span> 1b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:14</a>, 40 (sobre sua condição social, veja New Docs 2, 27f). BHHW II 1115; CHemer em New Docs 3, 53–55; LSchottroff, Let the Oppressed Go Free, tradução de AKidder ’93 [’91], 131–37.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυκαονία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυκαονία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Xenofonte e outros; ins) Licaônia, província no interior da Ásia Menor, limitada por Capadócia, Galácia (veja <span class=\"greek\">Γαλατία</span>), Frígia, Pisídia e Cilícia. Suas principais cidades eram as visitadas por Paulo: Listra, Icônio e Derbe. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:6</a>.—Ramsay, Histor. Comm. sobre Gal 1899, 19ff.; Pauly-W. XIII 2253ff; Kl. Pauly III 807f; BHHW II 1115f; Haenchen no lugar citado</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυκαονιστί</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυκαονιστί</span> advérbio: na língua licaônica, dialeto outrora falado na Licaônia, hoje não conhecido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:11</a>.—PKretschmer, Einleitung in die Geschichte der griech. Sprache 1896, 396; KHoll, Her. 43, 1908, 240ff.; Haenchen no lugar citado—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυκία, ας, ἡ</h1><div class=\"entry-meta\"><span>topônimo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυκία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Heródoto e outros; ins; 1 Macc 15:23; SibOr) Lícia, território saliente na costa meridional da Ásia Menor, entre Cária e Panfília <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:5</a>.—IAsMinLyk; EKalinka, Zur histor. Topographie Lykiens: HKiepert Festschr., 1898, 161f; Kl. Pauly III 809f; BHHW II 1118.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Homero e outros; ins, pap, LXX, Test12Patr; JosAs 12:10; SibOr 8, 41; 13, 28; Philo; Just., A I, 58, 2; empréstimo na literatura rabínica, mas veja KRengstorf, ELittmann Festschr., ’35, 55–62)</p><p class=\"entry-text\">① lobo, literalmente, como símbolo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:12ab</a>; D 16:3 (em todas essas passagens, em oposição a ovelhas; cf. Dio Chrys. 64 [14], 2; Philostrat., Vi. Apoll. 8, 22; Philo, Praem. 86; Just., A I, 58, 2; Iren. 1, Prologue 2 [Harv. I 4, 3]; Did., Gen. 86, 18).</p><p class=\"entry-text\">② pessoa feroz ou cruel, lobo em sentido metafórico, extensão da acepção 1 (em linguagem figurada desde Il. 4, 471; 16, 156; Epict. 1, 3, 7 al.; cf. Zeph 3:3; Jer 5:6; Ez 22:27; Ródon [em Eus., HE 5, 13, 4] refere-se a Marcião como <span class=\"greek\">ὁ</span> <span class=\"greek\">Ποντικὸς</span> <span class=\"greek\">λύκος</span>), quanto a pessoas malignas IPhld 2:2; 2 Cl 5:2–4 (proveniente de um evangelho não canônico). <span class=\"greek\">λ</span>. <span class=\"greek\">ἅρπαγες</span> lobos vorazes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:15</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">βαρεῖς</span> lobos ferozes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:29</a>.—B. 185. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυμαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυμαίνω</span> infinitivo do 1º aoristo <span class=\"greek\">λυμᾶναι</span>; imperfeito médio <span class=\"greek\">ἐλυμαινόμην</span>; futuro, 3ª pessoa do singular <span class=\"greek\">λυμανεῖται</span> LXX; predominantemente, e nos tempos mais antigos exclusivamente, empregado como médio depoente (cf. <span class=\"greek\">λῦμα</span> «sujeira deixada pela lavagem»; Aeschyl., Hdt.+; ins, pap, LXX; En 19:1; EpArist 164; Philo; Jos., Bell. 2, 271; 4, 534 al.; Ath., R. 1 p. 49, 8 [com dativo]) causar dano a, prejudicar, estragar, arruinar, destruir (so Thu. e outros) <span class=\"greek\">τὶ</span>, algo <span class=\"greek\">Σαῦλος</span> <span class=\"greek\">ἐλυμαίνετο</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> Saulo estava causando graves danos à comunidade (cristã) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:3</a>. Quanto a glutões que, por sua intemperança, prejudicam <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">αὐτῶν</span> seus corpos Hv 3, 9, 3a (Epict. 3, 22, 87 <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">λυμαίνεται</span>=ele prejudica seu corpo).—Também empregado na voz passiva (UPZ 187, 20 [127/126 a.C.]; M-M s.v. <span class=\"greek\">λυμαίνομαι</span>) <span class=\"greek\">λυμαίνεται</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">σὰρξ</span> <span class=\"greek\">αὐτῶν</span> seus corpos ficam prejudicados Hv 3, 9, 3b (cf. Jos., Ant. 12, 256 <span class=\"greek\">λ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">σώματα</span>).—A forma ativa <span class=\"greek\">λυμαίνω</span> aparece bastante tardiamente (Libanius, Decl. 13, 6 vol. VI p. 10, 13 F.; PGM 13, 302 <span class=\"greek\">πῦρ</span>, <span class=\"greek\">οὐ</span> <span class=\"greek\">μή</span> <span class=\"greek\">μου</span> <span class=\"greek\">λυμάνῃς</span> <span class=\"greek\">σάρκα</span>; Herm. Wr. 10, 20; TestAbr A). Possui o mesmo significado <span class=\"greek\">πόλιν</span> <span class=\"greek\">λυμᾶναι</span> destruir uma cidade Hv 4, 1, 8. <span class=\"greek\">τινά</span> ferir alguém 4, 2, 4.—B. 760. DELG s.v. <span class=\"greek\">λῦμα</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυπέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυπέω</span> 1º aoristo <span class=\"greek\">ἐλύπησα</span>; perfeito <span class=\"greek\">λελύπηκα</span>. Na voz passiva: 1º futuro <span class=\"greek\">λυπηθήσομαι</span>; 1º aoristo <span class=\"greek\">ἐλυπήθην</span>; perfeito <span class=\"greek\">λελύπημαι</span> (de <span class=\"greek\">λύπη</span>, «dor, tristeza»; Hes.+) em geral, «entristecer, causar dor».</p><p class=\"entry-text\">① causar grave sofrimento mental ou emocional, afligir, irritar, ofender, insultar; voz ativa, <span class=\"greek\">τινά</span>, alguém (Test Abr A 8 p. 86, 9 [Stone p. 20]; Dio Chrys. 28 [45], 3; BGU 531 II, 18 [século I d.C.], frequentemente no sentido de aborrecer, irritar, ofender TestSol 2:3 D; Herodas 5, 7, 3; Ar. 15:7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:2a</a>; 7:8ab. O objeto de <span class=\"greek\">λυπεῖν</span> também pode ser uma divindade (Diod S 1, 65, 7; 8 <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>; escólio a Apollon. Rhod. 2, 313 <span class=\"greek\">λ</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">Δία</span>; cf. <span class=\"greek\">τοὺ</span> <span class=\"greek\">ἀγγέλους</span> <span class=\"greek\">μου</span> ApcSed 14:10) <span class=\"greek\">μὴ</span> <span class=\"greek\">λυπεῖτε</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἅγιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:30</a>; Hm 10, 2, 2; 10, 3, 2ab; cf. 10, 2, 4. <span class=\"greek\">χάριν</span> Dg 11:7. Em <span class=\"greek\">εἴ</span> <span class=\"greek\">τις</span> <span class=\"greek\">λελύπηκεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:5</a> <span class=\"greek\">λ</span>. empregado absolutamente certamente significa mais que causar dor ou aborrecimento. Em Polieno 8, 47, refere-se à grave humilhação ou ultraje experimentado por um rei deposto por seus súditos.</p><p class=\"entry-text\">② experimentar tristeza ou aflição, na voz passiva</p><p class=\"entry-text\">ⓐ aoristo <span class=\"greek\">λυπηθῆναι</span> ficar triste, entristecer-se, afligir-se (BGU 1079, 9 [41 d.C.]; Esth 2:21; Ps 54:3; 2 Esdr 15:6; TestJob, Test12Patr, GrBar; Jos., Ant. 8, 356) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:9</a>; AcPl Ha 7, 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:4</a>; 7:9a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:6</a>; Dg 1. Com <span class=\"greek\">σφόδρα</span> (Da 6:15 LXX; 1 Macc 10:68; JosAs 8:8 e outros) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:23</a>; 18:31; GJs 1:3; 2:4; AcPl Ha 7, 15; com <span class=\"greek\">λίαν</span> 1 Cl 4:3 (Gen 4:5 Caim se ofendeu). Com <span class=\"greek\">ὅτι</span> em seguida: entristecer-se porque (cf. En 102:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:17</a>. <span class=\"greek\">λυπηθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">μετάνοιαν</span> entristecer-se a ponto de arrepender-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:9b</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεόν</span> segundo a vontade de Deus versículos 9c, 11.</p><p class=\"entry-text\">ⓑ presente <span class=\"greek\">λυπεῖσθαι</span> estar triste, aflito, entristecer-se (La 1:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:13</a>. <span class=\"greek\">λυπῇ</span>; estás triste ou magoado? Hv 3, 1, 9b. <span class=\"greek\">λυπούμενος</span> (estando) triste, pesaroso <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:22</a>; 26:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:22</a>; Hv 1, 2, 2; 3, 13, 2 (TestAbr A 7 p. 84, 9 [Stone p. 16]; Jos., Vi. 208). (Em oposição a <span class=\"greek\">χαίρων</span>, como em Dio Chrys. 50 [67], 5; Philo, Virt. 103) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:10</a>. <span class=\"greek\">λυπουμένου</span> (<span class=\"greek\">μου</span>) <span class=\"greek\">ὅτι</span> porque, Hv 3, 1, 9a. <span class=\"greek\">ἤμην</span> <span class=\"greek\">λυπούμενος</span> 1, 2, 1. <span class=\"greek\">ὁ</span> <span class=\"greek\">λυπούμενος</span> o homem entristecido (Ael. Aristid. 46 p. 404 D.) m 10, 3, 3. <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἐμοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:2b</a> indica a origem da dor ou tristeza. <span class=\"greek\">ἤρξατο</span> <span class=\"greek\">λυπεῖσθαι</span> começou a entristecer-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:37</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:19</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">διά</span> <span class=\"greek\">τι</span>, por causa de algo (escólio a Apollon. Rhod. 4, 1090; JosAs 24:19 <span class=\"greek\">δι</span>’ <span class=\"greek\">Ἀσενέθ</span>; ParJer 4:11 <span class=\"greek\">διὰ</span> <span class=\"greek\">σέ</span>): <span class=\"greek\">εἰ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">βρῶμα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀδελφὸς</span> <span class=\"greek\">λυπεῖται</span> se os sentimentos de um irmão são feridos por causa de alimento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:15</a> (mas <span class=\"greek\">λ</span>. também pode significar prejudicar, causar dano: X., Mem. 1, 6, 6, Cyr. 6, 3, 13). <span class=\"greek\">μὴ</span> <span class=\"greek\">λυπείσθω</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">εὐσεβὴς</span> <span class=\"greek\">ἐάν</span> o homem piedoso não deve entristecer-se se 2 Cl 19:4. <span class=\"greek\">λ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>, por causa de algo (X., Mem. 3, 9, 8; Lucian, Dial. Mort. 13, 5, Tox. 24; Artem. 2, 60; PGrenf II, 36, 9 [95 a.C.]; Jon 4:9; ApcMos 39 p. 21, 1 Tdf.; Philo, Abr. 22; Just., D. 107, 3) Hm 10, 2, 3; cf. Hs 6, 3, 1. <span class=\"greek\">ἐλυπεῖτο</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μικρῶς</span> (Hieronymus) estava muito perturbado com sua esposa, que havia demonstrado interesse pela mensagem de Paulo AcPl Ha 4, 16f (com <span class=\"greek\">περί</span>, como em Da 6:18 LXX; ApcMos 18 p. 9, 13 Tdf.).—Imperfeito <span class=\"greek\">ἐλυπούμην</span>, eu estava triste GPt 7:26; cf. 14:59 (TestSol 2:2 D; TestSim 4:3; ParJer 7:30); com <span class=\"greek\">σφόδρα</span> (JosAs 24:1) GJs 1:4 (aoristo, variante textual).—DELG s.v. <span class=\"greek\">λύπη</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύπη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύπη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λυπέω</span>; Aeschyl., Hdt.+) dor da mente ou do espírito, pesar, tristeza, aflição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:6</a>; Hm 10, 1, 2; 10, 2, 1–6; 10, 3, 1; 3f; AcPl Ha 6, 16. <span class=\"greek\">περισσοτέρα</span> <span class=\"greek\">λ</span>. tristeza excessiva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:7</a>. Em oposição a <span class=\"greek\">χαρά</span> (X., Hell. 7, 1, 32; Eth. Epic. col. 3, 16; Philo, Abr. 151, Leg. ad Gai. 15; JosAs 9:1; ApcMos 39) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:11</a>. <span class=\"greek\">λύπην</span> <span class=\"greek\">ἔχειν</span> sentir dor, estar triste (Dio Chrys. 46 [63], 1; ApcMos 3) durante o parto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:21</a>; cf. v. 22. <span class=\"greek\">λ</span>. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> sentir pesar por causa de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:3</a>. <span class=\"greek\">λύπην</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">ἔχειν</span> tristeza sobre tristeza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:27</a>; em oposição a <span class=\"greek\">πολυτέλεια</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἔχουσα</span> riqueza sem sofrimento Hs 1:10. <span class=\"greek\">λ</span>. <span class=\"greek\">μοί</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">μεγάλη</span> sinto profunda dor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:2</a> (cf. Tobit 3:6; TestJud 23:1 <span class=\"greek\">πολλὴ</span> <span class=\"greek\">λύπη</span> <span class=\"greek\">μοί</span> <span class=\"greek\">ἐστι</span>.—<span class=\"greek\">λ</span>. <span class=\"greek\">μεγάλη</span> como em Jon 4:1; TestJob 34:5; ApcMos 9). <span class=\"greek\">βαλεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">λύπην</span> mergulhar alguém na tristeza 1 Cl 46:9. <span class=\"greek\">τὸ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πάλιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">ὑμᾶς</span> <span class=\"greek\">ἐλθεῖν</span> não voltar a vós em tristeza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:1</a>. <span class=\"greek\">τί</span> … <span class=\"greek\">σεαυτῷ</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">ἐπισπᾶσαι</span> por que estás atraindo tristeza sobre ti mesmo? Hs 9, 2, 6. <span class=\"greek\">ἀποβαλεῖν</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">λ</span>. deixar toda a tristeza de lado Hv 4, 3, 4; <span class=\"greek\">ἀποθέμενον</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. AcPl BMM recto 7 (para essa passagem, AcPl Ha 8, 8: <span class=\"greek\">το</span>]|[<span class=\"greek\">κατηφ</span>]<span class=\"greek\">ὲ̣̣</span> <span class=\"greek\">ἀποθέμενον</span>, conforme reconstituído por Schmidt, mas a respeito disso veja <span class=\"greek\">κατηφής</span>). Também <span class=\"greek\">αἴρειν</span> <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. Hm 10, 1, 1 (em oposição a <span class=\"greek\">ἱλαρότης</span> 10, 3, 1). <span class=\"greek\">ἐξέπτη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὐτοῦ</span> sua ansiedade (quanto ao combate com feras) dissipou-se AcPl Ha 3, 17. <span class=\"greek\">συγκόπτεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span> ser esmagado pela tristeza Hv 5:4. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. por causa da tristeza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:45</a> (TestJos 8:5 <span class=\"greek\">συνείχετο</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span>; ParJer 7:26 <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">διαφθαρῇ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>.; cf. UPZ 18, 13 [163 a.C.] <span class=\"greek\">ἀποθνήσκει</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>.; Jos., Ant. 6, 337). <span class=\"greek\">ἐκ</span> <span class=\"greek\">λύπης</span> contra a vontade, com relutância <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:7</a> (cf. Soph., O.C. 1636f sobre a generosa aceitação de Teseu, <span class=\"greek\">οὐκ</span> <span class=\"greek\">οἴκτου</span> <span class=\"greek\">μέτα</span>, da última ordem de Édipo; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:9</a>; quanto à gramática, cf. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λύπης</span> Aesop, Fab. 275 P.; JosAs 29:9). <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. em tristeza AcPl Ha 5, 24. <span class=\"greek\">ἡ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">λ</span>. tristeza aprovada por Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 7:10a</a> (conduzindo à <span class=\"greek\">μετάνοια</span>, como em Plut., Mor. 961d). Em oposição a isso <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">λύπη</span> a tristeza do mundo v. 10b. <span class=\"greek\">λύπην</span> <span class=\"greek\">ἐπάγειν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> causar tristeza ao espírito Hm 3:4. <span class=\"greek\">λύπη</span> personificada Hs 9, 15, 3.—Plural: (Demosth., Ep. 2, 25; Dio Chrys. 80 [30], 14; Gen 3:16f; 5:29; Pr 15:13; 31:6; PsSol 4:15; ParJer 7:36 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">λ</span>.) <span class=\"greek\">αἱ</span> <span class=\"greek\">πρότεραι</span> <span class=\"greek\">λῦπαι</span> as tristezas anteriores Hv 3, 13, 2. <span class=\"greek\">ὑποφέρειν</span> <span class=\"greek\">λύπας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:19</a>. <span class=\"greek\">παλαιοῦσθαι</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">λύπαις</span> envelhecer pelas tristezas Hv 3, 11, 3.—B. 1118. BHHW III 2021ff. Schmidt, Syn. II 574–95; DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυπηρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυπηρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">λύπη</span>; trágicos, Heródoto e outros; pap, LXX, Philo; Jos., Ant. 15, 61)</p><p class=\"entry-text\">① doloroso, aflitivo, em sentido ativo com <span class=\"greek\">τινί</span>, para alguém (PPetr II, 13 [19], 13 [século III a.C.] <span class=\"greek\">οὐθέν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">γενηθῇ</span> <span class=\"greek\">λυπηρόν</span>; Gen 34:7; Jos., Ant. 17, 175; Tat. 14, 2) <span class=\"greek\">ἀμφότερα</span> <span class=\"greek\">λυπηρά</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> Hm 10, 2, 4.</p><p class=\"entry-text\">② triste, pesaroso, abatido, em sentido passivo <span class=\"greek\">ἀνήρ</span> (Pr 17:22) em oposição a <span class=\"greek\">ἱλαρός</span> 10, 3, 2.—DELG s.v. <span class=\"greek\">λύπη</span>. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυσανίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυσανίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (quanto ao genitivo, veja Mlt-H. 119) Lisânias, tetrarca de Abilene <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a>. Houve um Lisânias, filho do dinasta Ptolomeu de Cálcis, que governou de 40–36 a.C. e foi executado por Marco Antônio. Se Lucas tivesse em mente esse Lisânias (assim HHoltzmann e Wlh., no lugar citado, e E Schwartz, NGG 1906, 370f), teria cometido grave erro cronológico. Mas houve um Lisânias mais jovem no período 25–30 d.C., ao qual se aplicam melhor as expressões de Josefo <span class=\"greek\">Ἄβιλαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Λυσανίου</span> (Ant. 19, 275) e <span class=\"greek\">Ἀβέλλα</span> (=<span class=\"greek\">Ἄβιλα</span>), como <span class=\"greek\">Λυσανία</span> <span class=\"greek\">τετραρχία</span> (20, 138) bem como as inscrições CIG 4521=OGI 606 e IGR III, 1086; CIG 4523 fazem referência.—Schürer I 568–70; EKlostermann e Zahn no lugar citado; RSavignac, Texte complet de l’inscription d’Abila relative à Lysanias: RB nova série 9, 1912, 533–40; Ramsay, Bearing 297–300; EMeyer I 47ff; Boffo, Iscrizioni 171–76 (fontes e bibliografia p. 171); Hemer, Acts 159f; Schürer I 567–69; DACL X ’31, 405–11; Kl. Pauly III 831.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λυσίας, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λυσίας</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (literatura, inscrições, papiros, LXX, Josefo) (Cláudio) Lísias (veja <span class=\"greek\">Κλαύδιος</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:26</a>; 24:7, 22; Haenchen no lugar citado</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λύσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λύσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λύω</span>; Hom.+; Diod S 18, 25, 2 [<span class=\"greek\">λύσις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κακῶν</span>=resolução, remoção de dificuldades]; ins, pap, LXX; En 5:6; TestSim 3:4; Philo; Jos., Ant. 9, 70; Mel., P. 55, 405; Ath. 16, 4) libertação, separação, no casamento, divórcio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:27</a>.—DELG s.v. <span class=\"greek\">λύω</span>. M-M. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυσιτελέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυσιτελέω</span> (<span class=\"greek\">λυσιτελής</span> adjetivo [veja <span class=\"greek\">λύω</span>, <span class=\"greek\">τέλος</span> 5]=«cobrindo as despesas realizadas» [quanto ao aspecto comercial, veja Schmidt, Syn. IV 162f], daí «útil, vantajoso»; Heródoto, Aristófanes e outros; LXX; Jos., Ant. 15, 110 al.) ser vantajoso, ser melhor, impessoalmente <span class=\"greek\">λυσιτελεῖ</span> (futuro <span class=\"greek\">λυσιτελήσει</span> LXX) é melhor, é vantajoso (Pla. [Crat. 417 b] e outros) com dativo (Dio Chrys. 48 [65], 3; SIG 344, 96 [cerca de 303 a.C.]; PHamb 27, 17 [250 a.C.]; Tob 3:6; Philo, Det. Pot. Ins. 68) <span class=\"greek\">λυσιτελεῖ</span> <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">περίκειται</span> … <span class=\"greek\">ἤ</span> <span class=\"greek\">ἵνα</span> seria melhor para tal pessoa que … do que <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:2</a> (Andoc. 1, 125 <span class=\"greek\">τεθνάναι</span> <span class=\"greek\">λυσιτελεῖ</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ζῆν</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λυσσάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λυσσάω</span> (Sófocles e outros; SibOr 5, 96) estar furioso, estar raivoso, quanto a cães (Aristófanes e outros) <span class=\"greek\">κύνες</span> <span class=\"greek\">λυσσῶντες</span> cães raivosos (figuradamente, como em Josefo, Bell. 6, 196) IEph 7:1.—DELG s.v. <span class=\"greek\">λύσσα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0221-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λύστρα</h1><div class=\"entry-meta\"><span>topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λύστρα</span> (Ptolem. 5, 4, 12; OGI 536; cf. Pliny, Nat. Hist. 5, 147; CIL III Suppl. 6786; 6974) acusativo <span class=\"greek\">Λύστραν</span> (mas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:5</a> o códice A apresenta <span class=\"greek\">Λύστρα</span>); dativo <span class=\"greek\">Λύστροις</span> (quanto à sua declinação, veja B-D-F §57; Mlt. 48; Mlt-H. 147; Thackeray 167f) <span class=\"greek\">ἡ</span> ou <span class=\"greek\">τά</span>, Listra, cidade da Licaônia na Ásia Menor, onde Paulo fundou uma igreja. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:6</a>, 8, 21; 16:1f; 27:5 variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:11</a>; AcPl Ant 13, 21 (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">Λύστραν</span> Aa I 237, 4).—ABludau, Pls in L., <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:7</a>–21: Der Katholik 87, 1907, 91–113; 161–83; WCalder, Zeus and Hermes at Lystra: Exp. 7th ser., 10, 1910, 1–6, também The ‘Priest’ of Zeus at Lystra: ibid. 148–55; AWikenhauser, D. AG 1921, 362f; LCurtius, Zeus u. Hermes ’31; ACook, Zeus III/2, ’40, 1071; MMeunier, Apoll. de Ty. ou le séjour d’un dieu parmi les hommes ’36; SEitrem, ConNeot 3, ’39, 9–12; Pauly-W. XIV 71f; Kl. Pauly III 846; Haenchen no lugar citado; BAFCS II 81–85.—M-M.</p></section></article>"};
